begin;
do $$begin if not exists(select 1 from spot_private.privacy_environment where environment='staging')then raise exception 'BOARD_STAGING_ONLY';end if;end$$;
create table spot_private.board_posts(id uuid primary key default gen_random_uuid(),venue_id uuid not null references public.venues(id)on delete cascade,author_id uuid not null references auth.users(id)on delete cascade,body text not null check(char_length(body)between 1 and 280 and body=btrim(body)),created_at timestamptz not null default clock_timestamp(),expires_at timestamptz not null default clock_timestamp()+interval '24 hours',hidden boolean not null default false,revision bigint not null default 0);
create index board_feed on spot_private.board_posts(venue_id,created_at desc,id desc);
create table spot_private.board_reactions(post_id uuid references spot_private.board_posts(id)on delete cascade,user_id uuid references auth.users(id)on delete cascade,kind text not null check(kind in('❤️','👀','😂','🔥')),primary key(post_id,user_id));
create table spot_private.board_quota(user_id uuid references auth.users(id)on delete cascade,venue_id uuid references public.venues(id)on delete cascade,day date,used integer not null check(used between 1 and 3),primary key(user_id,venue_id,day));
create table spot_private.board_receipts(user_id uuid references auth.users(id)on delete cascade,operation_id uuid,action text not null,fingerprint text not null,result_id uuid,created_at timestamptz not null default clock_timestamp(),primary key(user_id,operation_id));
create table spot_private.board_reports(id uuid primary key default gen_random_uuid(),post_id uuid references spot_private.board_posts(id)on delete cascade,reporter_id uuid references auth.users(id)on delete cascade,reason text not null check(reason in('harassment','fake_profile','underage','inappropriate','other')),state text not null default 'open'check(state in('open','under_review','closed')),revision bigint not null default 0,assigned_to uuid references auth.users(id)on delete set null,claim_until timestamptz,created_at timestamptz not null default clock_timestamp(),closed_at timestamptz,unique(post_id,reporter_id));
create table spot_private.board_audit(id uuid primary key default gen_random_uuid(),actor_id uuid references auth.users(id)on delete cascade,report_id uuid references spot_private.board_reports(id)on delete cascade,action text not null,operation_id uuid unique,fingerprint text not null,created_at timestamptz not null default clock_timestamp());
-- Evidence has no account/profile identifier; retained only under an explicit existing safety hold.
create table spot_private.board_evidence(hold_id uuid primary key references spot_private.safety_holds(id)on delete cascade,body text not null check(char_length(body)<=280),reason text not null,archived_at timestamptz not null default clock_timestamp());
do $$declare t text;begin foreach t in array array['board_posts','board_reactions','board_quota','board_receipts','board_reports','board_audit','board_evidence']loop execute format('alter table spot_private.%I enable row level security',t);execute format('revoke all on spot_private.%I from public,anon,authenticated',t);end loop;end$$;
create function spot_private.board_eligible(person uuid)returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from spot_private.privacy_environment where environment='staging')and spot_private.age_eligible(person)and exists(select 1 from auth.users u where u.id=person and not u.is_anonymous and coalesce((to_jsonb(u)->>'banned_until')::timestamptz,'-infinity')<=now())and exists(select 1 from public.profiles where id=person)and not exists(select 1 from spot_private.moderation_roles where user_id=person and active)and not exists(select 1 from spot_private.account_deletions where user_id=person)and not exists(select 1 from spot_private.suspensions where user_id=person and revoked_at is null and(until_at is null or until_at>now()));$$;
create function spot_private.board_member(place uuid)returns boolean language sql stable security definer set search_path='' as $$select spot_private.board_eligible(auth.uid())and exists(select 1 from spot_private.tribe_memberships m join public.venues v on v.id=m.venue_id where m.user_id=auth.uid()and m.venue_id=place and v.active);$$;
create function spot_private.board_publication(p spot_private.board_posts)returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('id',p.id,'text',p.body,'created_at',p.created_at,'expires_at',p.expires_at,'can_delete',p.author_id=auth.uid(),'reactions',(select coalesce(jsonb_object_agg(kind,n),'{}'::jsonb)from(select kind,count(*)n from spot_private.board_reactions where post_id=p.id group by kind)c),'my_reaction',(select kind from spot_private.board_reactions where post_id=p.id and user_id=auth.uid()));$$;
create function spot_private.board_lock()returns void language plpgsql security definer set search_path='' as $$begin perform pg_advisory_xact_lock(hashtextextended('privacy-retention',23));end$$;
create function public.board_feed(place uuid,cursor_time timestamptz default null,cursor_id uuid default null,page_size integer default 30)returns jsonb language plpgsql stable security definer set search_path='' as $$declare data jsonb;begin
 if not coalesce(spot_private.board_member(place),false)then raise exception 'BOARD_ACCESS'using errcode='42501';end if;
 if page_size is null or page_size not between 1 and 50 or(cursor_time is null)<>(cursor_id is null)then raise exception 'BOARD_INPUT';end if;
 select coalesce(jsonb_agg(value order by created_at desc,id desc),'[]')into data from(select spot_private.board_publication(p)value,p.created_at,p.id from spot_private.board_posts p where venue_id=place and not hidden and expires_at>clock_timestamp()and spot_private.board_eligible(author_id)and(cursor_time is null or(p.created_at,p.id)<(cursor_time,cursor_id))order by p.created_at desc,p.id desc limit page_size+1)x;
 return jsonb_build_object('items',case when jsonb_array_length(data)>page_size then data-page_size else data end,'more',jsonb_array_length(data)>page_size,'remaining',3-coalesce((select used from spot_private.board_quota where user_id=auth.uid()and venue_id=place and day=(clock_timestamp()at time zone 'Europe/Rome')::date),0));end$$;
-- Time-bounded creation nonce: old requests cannot become new posts after receipt purge.
create function public.board_operation(place uuid)returns uuid language plpgsql security definer set search_path='' as $$declare stamp text;raw text;begin
 if not coalesce(spot_private.board_member(place),false)then raise exception 'BOARD_ACCESS'using errcode='42501';end if;
 stamp:=lpad(to_hex(floor(extract(epoch from clock_timestamp())*1000)::bigint),12,'0');raw:=replace(gen_random_uuid()::text,'-','');return(substr(stamp,1,8)||'-'||substr(stamp,9,4)||'-7'||substr(raw,14,3)||'-'||substr(raw,17,4)||'-'||substr(raw,21,12))::uuid;end$$;
create function spot_private.board_operation_valid(op uuid)returns boolean language plpgsql stable security definer set search_path='' as $$declare raw text:=replace(op::text,'-','');stamp timestamptz;duration interval;begin
 if op is null or substr(raw,13,1)<>'7'then return false;end if;
 stamp:=to_timestamp((('x'||substr(raw,1,12))::bit(48)::bigint)/1000.0);select p.duration into duration from spot_private.retention_policies p where category='board_metadata';return stamp<=clock_timestamp()and stamp>=clock_timestamp()-duration;end$$;
create function public.board_create(place uuid,message_text text,operation_id uuid)returns uuid language plpgsql security definer set search_path='' as $$declare text_value text:=btrim(message_text);fp text;prior spot_private.board_receipts;pid uuid;stamp timestamptz;d date;begin
 perform spot_private.board_lock();perform spot_private.photo_owner_lock(auth.uid());
 if not coalesce(spot_private.board_member(place),false)then raise exception 'BOARD_ACCESS'using errcode='42501';end if;
 if not coalesce(spot_private.board_operation_valid(operation_id),false)then raise exception 'BOARD_OPERATION_EXPIRED';end if;
 if operation_id is null or text_value is null or char_length(text_value)not between 1 and 280 then raise exception 'BOARD_TEXT';end if;
 fp:=md5(place::text||':'||text_value);select * into prior from spot_private.board_receipts r where r.user_id=auth.uid()and r.operation_id=board_create.operation_id;
 if found then if prior.action<>'create'or prior.fingerprint<>fp then raise exception 'BOARD_OPERATION_CONFLICT';end if;return prior.result_id;end if;
 stamp:=clock_timestamp();d:=(stamp at time zone 'Europe/Rome')::date;
 if coalesce((select used from spot_private.board_quota where user_id=auth.uid()and venue_id=place and day=d),0)>=3 then raise exception 'BOARD_DAILY_LIMIT';end if;
 insert into spot_private.board_quota values(auth.uid(),place,d,1)on conflict(user_id,venue_id,day)do update set used=board_quota.used+1;
 insert into spot_private.board_posts(venue_id,author_id,body,created_at,expires_at)values(place,auth.uid(),text_value,stamp,stamp+interval '24 hours')returning id into pid;
 insert into spot_private.board_receipts(user_id,operation_id,action,fingerprint,result_id)values(auth.uid(),operation_id,'create',fp,pid);return pid;end$$;
create function public.board_react(target_post uuid,reaction text,operation_id uuid)returns void language plpgsql security definer set search_path='' as $$declare p spot_private.board_posts;prior spot_private.board_receipts;fp text;begin
 perform spot_private.board_lock();perform spot_private.photo_owner_lock(auth.uid());select * into p from spot_private.board_posts where id=target_post for update;
 if not found or not coalesce(spot_private.board_member(p.venue_id),false)or p.hidden or p.expires_at<=clock_timestamp()or not spot_private.board_eligible(p.author_id)then raise exception 'BOARD_ACCESS'using errcode='42501';end if;
 if operation_id is null or reaction is not null and reaction not in('❤️','👀','😂','🔥')then raise exception 'BOARD_INPUT';end if;
 fp:=md5(target_post::text||':'||coalesce(reaction,'remove'));select * into prior from spot_private.board_receipts r where r.user_id=auth.uid()and r.operation_id=board_react.operation_id;
 if found then if prior.action<>'react'or prior.fingerprint<>fp then raise exception 'BOARD_OPERATION_CONFLICT';end if;return;end if;
 if reaction is null then delete from spot_private.board_reactions where post_id=target_post and user_id=auth.uid();else insert into spot_private.board_reactions values(target_post,auth.uid(),reaction)on conflict(post_id,user_id)do update set kind=excluded.kind;end if;
 insert into spot_private.board_receipts(user_id,operation_id,action,fingerprint)values(auth.uid(),operation_id,'react',fp);end$$;
create function spot_private.board_capture(pid uuid)returns void language plpgsql security definer set search_path='' as $$begin
 insert into spot_private.board_evidence(hold_id,body,reason)select h.id,p.body,coalesce(r.reason,'other')from spot_private.safety_holds h join spot_private.board_posts p on p.id=pid left join spot_private.board_reports r on r.post_id=p.id and h.category='board_reports'and h.target=r.id::text where h.released_at is null and((h.category='board_posts'and h.target=p.id::text)or r.id is not null)on conflict(hold_id)do nothing;end$$;
create function public.board_delete(target_post uuid,operation_id uuid)returns void language plpgsql security definer set search_path='' as $$declare p spot_private.board_posts;prior spot_private.board_receipts;begin
 perform spot_private.board_lock();perform spot_private.photo_owner_lock(auth.uid());if auth.uid()is null or not exists(select 1 from auth.users where id=auth.uid())or operation_id is null then raise exception 'BOARD_ACCESS'using errcode='42501';end if;
 select * into prior from spot_private.board_receipts r where r.user_id=auth.uid()and r.operation_id=board_delete.operation_id;if found then if prior.action<>'delete'or prior.fingerprint<>target_post::text then raise exception 'BOARD_OPERATION_CONFLICT';end if;return;end if;
 select * into p from spot_private.board_posts where id=target_post for update;if found and p.author_id<>auth.uid()then raise exception 'BOARD_ACCESS'using errcode='42501';end if;
 if found then perform spot_private.board_capture(p.id);delete from spot_private.board_posts where id=p.id;end if;
 insert into spot_private.board_receipts(user_id,operation_id,action,fingerprint)values(auth.uid(),operation_id,'delete',target_post::text);end$$;
create function public.board_report(target_post uuid,reason text,operation_id uuid)returns uuid language plpgsql security definer set search_path='' as $$declare p spot_private.board_posts;rid uuid;prior spot_private.board_receipts;fp text;begin
 perform spot_private.board_lock();perform spot_private.photo_owner_lock(auth.uid());select * into p from spot_private.board_posts where id=target_post for update;
 if not found or not coalesce(spot_private.board_member(p.venue_id),false)or p.hidden or p.expires_at<=clock_timestamp()or not spot_private.board_eligible(p.author_id)then raise exception 'BOARD_ACCESS'using errcode='42501';end if;
 if operation_id is null or reason is null or reason not in('harassment','fake_profile','underage','inappropriate','other')then raise exception 'BOARD_INPUT';end if;
 fp:=md5(target_post::text||':'||reason);select * into prior from spot_private.board_receipts r where r.user_id=auth.uid()and r.operation_id=board_report.operation_id;
 if found then if prior.action<>'report'or prior.fingerprint<>fp then raise exception 'BOARD_OPERATION_CONFLICT';end if;return prior.result_id;end if;
 insert into spot_private.board_reports(post_id,reporter_id,reason)values(target_post,auth.uid(),reason)on conflict(post_id,reporter_id)do update set reason=board_reports.reason returning id into rid;
 insert into spot_private.board_receipts(user_id,operation_id,action,fingerprint,result_id)values(auth.uid(),operation_id,'report',fp,rid);return rid;end$$;
-- A sanction permanently marks existing posts hidden, including sanctions originating in profile moderation.
create function spot_private.board_sanction()returns trigger language plpgsql security definer set search_path='' as $$begin if new.revoked_at is null and(new.until_at is null or new.until_at>clock_timestamp())then update spot_private.board_posts set hidden=true,revision=revision+1 where author_id=new.user_id and not hidden;end if;return new;end$$;
create trigger board_on_suspension after insert or update on spot_private.suspensions for each row execute function spot_private.board_sanction();
create function public.board_moderation_queue(filter text default 'open',cursor_time timestamptz default null,cursor_id uuid default null,page_size integer default 50)returns jsonb language plpgsql stable security definer set search_path='' as $$declare data jsonb;begin
 if not exists(select 1 from spot_private.privacy_environment where environment='staging')or not coalesce(public.is_moderator(),false)then raise exception 'BOARD_ACCESS'using errcode='42501';end if;
 if filter is null or filter not in('all','open','under_review','closed')or page_size is null or page_size not between 1 and 100 or(cursor_time is null)<>(cursor_id is null)then raise exception 'BOARD_INPUT';end if;
 select coalesce(jsonb_agg(to_jsonb(q)order by created_at,id),'[]')into data from(select r.id,r.reason,r.state queue_state,r.revision,r.created_at,p.id post_id,p.body text,p.hidden from spot_private.board_reports r join spot_private.board_posts p on p.id=r.post_id where(filter='all'or r.state=filter)and(cursor_time is null or(r.created_at,r.id)>(cursor_time,cursor_id))order by r.created_at,r.id limit page_size+1)q;
 return jsonb_build_object('staff_role',spot_private.moderation_role(),'items',case when jsonb_array_length(data)>page_size then data-page_size else data end,'more',jsonb_array_length(data)>page_size);end$$;
create function public.board_moderation_action(target_report uuid,action text,operation_id uuid,expected_revision bigint,duration_hours integer default null)returns jsonb language plpgsql security definer set search_path='' as $$declare r spot_private.board_reports;p spot_private.board_posts;prior spot_private.board_audit;fp text;staff text:=spot_private.moderation_role();begin
 if not exists(select 1 from spot_private.privacy_environment where environment='staging')or staff is null then raise exception 'BOARD_ACCESS'using errcode='42501';end if;
 if action is null or action not in('claim','review','dismiss','hide','warn','suspend','ban','resolve_author')or operation_id is null or expected_revision is null or(action='suspend'and(duration_hours is null or duration_hours not between 1 and 720))or(action<>'suspend'and duration_hours is not null)then raise exception 'BOARD_INPUT';end if;
 if action='ban'and staff<>'ADMIN'then raise exception 'BOARD_ACCESS'using errcode='42501';end if;
 perform spot_private.board_lock();fp:=md5(target_report::text||':'||action||':'||expected_revision||':'||coalesce(duration_hours,0));
 select * into prior from spot_private.board_audit where board_audit.operation_id=board_moderation_action.operation_id;
 if found then if prior.actor_id<>auth.uid()or prior.fingerprint<>fp then raise exception 'BOARD_OPERATION_CONFLICT';end if;if action<>'resolve_author'then return jsonb_build_object('completed',true);end if;end if;
 select * into r from spot_private.board_reports where id=target_report for update;if not found then raise exception 'BOARD_CASE';end if;
 select * into p from spot_private.board_posts where id=r.post_id for update;perform spot_private.photo_owner_lock(p.author_id);
 if r.revision<>expected_revision and prior.id is null then raise exception 'BOARD_STALE';end if;
 if r.assigned_to is not null and r.assigned_to<>auth.uid()and r.claim_until>clock_timestamp()then raise exception 'BOARD_CLAIMED';end if;
 if r.state='closed'and prior.id is null then raise exception 'BOARD_CLOSED';end if;
 if prior.id is null then insert into spot_private.board_audit(actor_id,report_id,action,operation_id,fingerprint)values(auth.uid(),r.id,action,operation_id,fp);end if;
 if action='resolve_author'then if r.state<>'under_review'or r.assigned_to is distinct from auth.uid()or coalesce(r.claim_until,'-infinity')<=clock_timestamp()then raise exception 'BOARD_CLAIM_REQUIRED';end if;return jsonb_build_object('author_id',p.author_id);end if;
 if action='claim'then update spot_private.board_reports set state='under_review',assigned_to=auth.uid(),claim_until=clock_timestamp()+interval '15 minutes',revision=revision+1 where id=r.id;
 else
 if action in('hide','suspend','ban')then update spot_private.board_posts set hidden=true,revision=revision+1 where id=p.id;end if;
 if action='suspend'and exists(select 1 from spot_private.suspensions where user_id=p.author_id and kind='ban'and revoked_at is null)then raise exception 'BOARD_BAN_RELEASE_REQUIRED';end if;
 if action in('suspend','ban')then insert into spot_private.suspensions(user_id,reason,kind,until_at)values(p.author_id,upper(r.reason),action,case when action='suspend'then clock_timestamp()+make_interval(hours=>duration_hours)end)on conflict(user_id)do update set reason=excluded.reason,kind=excluded.kind,until_at=excluded.until_at,revoked_at=null,created_at=clock_timestamp();end if;
 if action='warn'then insert into spot_private.moderation_audit(actor_id,report_id,action,note,operation_id,target_id,reason_code,previous_state,new_state,request)values(auth.uid(),null,'warn','',operation_id,p.author_id,upper(r.reason),'{}','{}','{}');end if;
 update spot_private.board_reports set state='closed',closed_at=clock_timestamp(),assigned_to=null,claim_until=null,revision=revision+1 where id=r.id;end if;
 return jsonb_build_object('completed',true);end$$;
-- Wrap RIGHTS without changing its existing categories or exposing author/reporter/receipts.
alter function public.my_rights_page(text,text,integer)rename to board_prior_rights_page;
revoke all on function public.board_prior_rights_page(text,text,integer)from public,anon,authenticated,service_role;
create function public.my_rights_page(section text,after_key text default '',page_size integer default 100)returns jsonb language plpgsql stable security definer set search_path='' as $$declare data jsonb;begin
 if section not in('board_posts','board_reactions','board_reports')then return public.board_prior_rights_page(section,after_key,page_size);end if;
 if not exists(select 1 from spot_private.privacy_environment where environment='staging')or auth.uid()is null or not exists(select 1 from auth.users where id=auth.uid())then raise exception 'RIGHTS_AUTH'using errcode='42501';end if;
 if page_size is null or page_size not between 1 and 100 or after_key is null or length(after_key)>200 then raise exception 'RIGHTS_INPUT';end if;
 select coalesce(jsonb_agg(jsonb_build_object('key',k,'data',value)order by k),'[]')into data from(select * from(
 select id::text k,jsonb_build_object('id',id,'text',body,'venue_id',venue_id,'created_at',created_at,'expires_at',expires_at)value from spot_private.board_posts where section='board_posts'and author_id=auth.uid()
 union all select post_id::text,jsonb_build_object('post_id',post_id,'kind',kind)from spot_private.board_reactions where section='board_reactions'and user_id=auth.uid()
 union all select id::text,jsonb_build_object('id',id,'reason',reason,'state',state,'created_at',created_at)from spot_private.board_reports where section='board_reports'and reporter_id=auth.uid())x where k>after_key order by k limit page_size+1)y;
 return jsonb_build_object('owner_id',auth.uid(),'section',section,'items',coalesce((select jsonb_agg(value)from(select value from jsonb_array_elements(data)with ordinality as e(value,n)where n<=page_size)x),'[]'::jsonb),'next_key',case when jsonb_array_length(data)>page_size then data->(page_size-1)->>'key'end);end$$;
revoke all on function public.my_rights_page(text,text,integer)from public,anon;grant execute on function public.my_rights_page(text,text,integer)to authenticated;
-- Delete prepares explicit held evidence, then cascades all ordinary content. PHOTO preparation stays intact.
alter function public.prepare_account_deletion(uuid)rename to board_prior_prepare_account_deletion;
revoke all on function public.board_prior_prepare_account_deletion(uuid)from public,anon,authenticated,service_role;
create function public.prepare_account_deletion(target_user uuid)returns void language plpgsql security definer set search_path='' as $$declare p record;begin perform spot_private.board_lock();perform spot_private.photo_owner_lock(target_user);for p in select b.id from spot_private.board_posts b where b.author_id=target_user or exists(select 1 from spot_private.board_reports r where r.post_id=b.id and r.reporter_id=target_user)loop perform spot_private.board_capture(p.id);end loop;perform public.board_prior_prepare_account_deletion(target_user);end$$;
revoke all on function public.prepare_account_deletion(uuid)from public,anon,authenticated;grant execute on function public.prepare_account_deletion(uuid)to service_role;
-- Duration is meaningful for reports/metadata; post purge is immediately eligible after product expiry.
insert into spot_private.retention_policies(category,duration)values('board_posts','1 second'),('board_reports','180 days'),('board_metadata','7 days');
alter function public.privacy_retention_run(text,uuid,boolean)rename to board_prior_retention_run;
do $$begin execute replace(pg_get_functiondef('public.board_prior_retention_run(text,uuid,boolean)'::regprocedure),'privacy_retention_run.','board_prior_retention_run.');end$$;
revoke all on function public.board_prior_retention_run(text,uuid,boolean)from public,anon,authenticated,service_role;
create function public.privacy_retention_run(category text,operation_id uuid,dry_run boolean default true)returns jsonb language plpgsql security definer set search_path='' as $$declare rule spot_private.retention_policies;prior spot_private.retention_runs;p record;n integer:=0;removed integer:=0;begin
 if category not in('board_posts','board_reports','board_metadata')then return public.board_prior_retention_run(category,operation_id,dry_run);end if;
 if not exists(select 1 from spot_private.privacy_environment where environment='staging')then raise exception 'BOARD_STAGING_ONLY';end if;
 if operation_id is null or dry_run is null then raise exception 'RETENTION_INPUT';end if;perform spot_private.board_lock();select * into prior from spot_private.retention_runs where retention_runs.operation_id=privacy_retention_run.operation_id;
 if found then if prior.category<>category or prior.dry_run<>dry_run then raise exception 'RETENTION_OPERATION_CONFLICT';end if;return jsonb_build_object('candidates',prior.candidates,'purged',prior.purged,'replay',true);end if;
 select * into rule from spot_private.retention_policies where retention_policies.category=privacy_retention_run.category;
 if not dry_run and((select paused from spot_private.retention_control)or not rule.enabled)then return jsonb_build_object('paused',true,'purged',0);end if;
 if category='board_posts'then for p in select id from spot_private.board_posts b where expires_at<=clock_timestamp()and not exists(select 1 from spot_private.board_reports r where r.post_id=b.id and r.state<>'closed')and not spot_private.retention_held('board_posts',b.id::text)and not exists(select 1 from spot_private.board_reports r where r.post_id=b.id and spot_private.retention_held('board_reports',r.id::text))loop n:=n+1;if not dry_run then delete from spot_private.board_posts where id=p.id;removed:=removed+1;end if;end loop;
 elsif category='board_reports'then for p in select id from spot_private.board_reports where state='closed'and closed_at<clock_timestamp()-rule.duration and not spot_private.retention_held('board_reports',id::text)loop n:=n+1;if not dry_run then delete from spot_private.board_reports where id=p.id;removed:=removed+1;end if;end loop;
 else select count(*)into n from spot_private.board_receipts where created_at<clock_timestamp()-rule.duration;if not dry_run then delete from spot_private.board_receipts where created_at<clock_timestamp()-rule.duration;get diagnostics removed=row_count;delete from spot_private.board_quota where day<(clock_timestamp()at time zone 'Europe/Rome')::date-extract(day from rule.duration)::integer;end if;end if;
 insert into spot_private.retention_runs(operation_id,category,policy_version,dry_run,candidates,purged)values(operation_id,category,rule.version,dry_run,n,removed);return jsonb_build_object('category',category,'candidates',n,'purged',removed,'dry_run',dry_run);end$$;
revoke all on function public.privacy_retention_run(text,uuid,boolean)from public,anon,authenticated;grant execute on function public.privacy_retention_run(text,uuid,boolean)to service_role;
do $$declare f record;begin for f in select p.oid::regprocedure s from pg_proc p join pg_namespace n on n.oid=p.pronamespace where(n.nspname='spot_private'and p.proname like 'board_%')or(n.nspname='public'and p.proname like 'board_%')loop execute format('revoke all on function %s from public,anon,authenticated',f.s);end loop;end$$;
grant execute on function public.board_operation(uuid),public.board_feed(uuid,timestamptz,uuid,integer),public.board_create(uuid,text,uuid),public.board_react(uuid,text,uuid),public.board_delete(uuid,uuid),public.board_report(uuid,text,uuid),public.board_moderation_queue(text,timestamptz,uuid,integer),public.board_moderation_action(uuid,text,uuid,bigint,integer)to authenticated;
notify pgrst,'reload schema';commit;
